#ifndef SCAMP_PREFIX_TABLE_HPP
#define SCAMP_PREFIX_TABLE_HPP
#include "scamptrie_base.h"
#include <vector>
#include <cstdint>

namespace scamp {
constexpr uint32_t null_hop=4194303;
inline uint64_t mask64(unsigned n) {
    return n==0 ? 0 : (~uint64_t(0) << (64-n));
}
inline ip6_t normalize(ip6_t p,unsigned n) {
    if(n<=64) return {p.hi & mask64(n),0};
    return {p.hi,p.lo & mask64(n-64)};
}
inline bool matches(ip6_t a,ip6_t b,unsigned n) {
    if(n<=64) return ((a.hi^b.hi)&mask64(n))==0;
    return a.hi==b.hi && ((a.lo^b.lo)&mask64(n-64))==0;
}
inline unsigned bit(ip6_t p,unsigned n) {
    return n<64 ? ((p.hi>>(63-n))&1) : ((p.lo>>(127-n))&1);
}
// Fragments at the end of an owner are padded on the right.  Never shift
// by the width of an integer, including at /0, /64 and /128.
inline unsigned extract(ip6_t p,unsigned start,unsigned count) {
    unsigned v=0;
    for(unsigned i=0;i<count;++i) v=(v<<1)|((start+i<128)?bit(p,start+i):0);
    return v;
}
inline ip6_t append(ip6_t p,unsigned start,unsigned count,unsigned value) {
    for(unsigned i=0;i<count;++i) {
        unsigned pos=start+i;
        uint64_t m=uint64_t(1)<<(pos<64?63-pos:127-pos);
        uint64_t& x=pos<64?p.hi:p.lo;
        if ((value>>(count-1-i))&1) x|=m; else x&=~m;
    }
    return p;
}

// Used only while checking/capturing an image, never as a substitute for
// loaded-image lookup.  This also detects exact duplicate serialized routes.
class PrefixTable {
    struct Node { int child[2]={-1,-1}; uint32_t hop=null_hop; };
    std::vector<Node> nodes;
public:
    PrefixTable() {nodes.emplace_back();}
    bool insert(ip6_t ip,unsigned len,uint32_t hop) {
        int at=0;
        for(unsigned i=0;i<len;++i) {
            unsigned b=bit(ip,i);
            int next=nodes[at].child[b];
            if(next<0) {next=int(nodes.size());nodes[at].child[b]=next;nodes.emplace_back();}
            at=next;
        }
        if(nodes[at].hop!=null_hop) return false;
        nodes[at].hop=hop;return true;
    }
    uint32_t lookup(ip6_t ip,unsigned maxlen=128) const {
        int at=0;uint32_t result=nodes[0].hop;
        for(unsigned i=0;i<maxlen;++i) {
            at=nodes[at].child[bit(ip,i)];
            if(at<0)break;
            if(nodes[at].hop!=null_hop)result=nodes[at].hop;
        }
        return result;
    }
};
}
#endif
